cd /workspace/tmp/tests && cat > fuzz3.py <<'PYEOF'
"""Language-membership fuzz (precise, cheap) + canonical form vs FAdo."""
import random, sys
sys.path[:0]=['/workspace/tmp/tests','/opt/emicro-deps','/workspace/project']
from lang import check_lang
from fado_ref import fado_image
from ebpf.create_dfa import create, registry_columns
seed=int(sys.argv[1]); count=int(sys.argv[2]); maxlen=int(sys.argv[3]) if len(sys.argv)>3 else 7
mode=sys.argv[4] if len(sys.argv)>4 else 'lang'
rng=random.Random(seed)
names=['A','B','C','D'][:rng.choice([2,3,4])]
labels=rng.sample(range(1,4294967294),len(names))
reg=[{'name':n,'label':labels[i]} for i,n in enumerate(names)]
cols,colmap=registry_columns(reg)
ops=['startswith','endswith','contains']
pool=[(rng.choice(ops), tuple(rng.choice(names) for _ in range(rng.randint(0,4)))) for _ in range(4)]
def gen():
    def path(m): return ','.join(rng.choice(names) for _ in range(rng.randint(0,m)))
    def pred(d):
        if d>=rng.randint(1,4) or rng.random()<0.4:
            if rng.random()<0.55: return 'match(%s)'%path(4)
            op,p=rng.choice(pool); return '%s(%s)'%(op,','.join(p))
        if rng.random()<0.25: return 'not(%s)'%pred(d+1)
        return '(%s %s %s)'%(pred(d+1),rng.choice(['and','or']),pred(d+1))
    return ' '.join('%s %s;'%(pred(0),rng.choice(['allow','allow','drop'])) for _ in range(rng.randint(0,4)))
bad=skip=done=0
for i in range(count):
    p=gen()
    try:
        if mode=='lang':
            b,t=check_lang(p,reg,maxlen)
            done+=1
            if b: bad+=1; print('LANG DIFF',repr(p))
        else:
            got=create(p,cols,colmap); got={'accept':list(got.accept),'rows':[list(r) for r in got.rows]}
            ref=fado_image(p,cols,colmap); done+=1
            if got!=ref:
                bad+=1; print('CANON DIFF',repr(p))
                print(' got',got['accept'],got['rows'][:5]); print(' ref',ref['accept'],ref['rows'][:5])
    except Exception as e:
        skip+=1; continue
    if bad>2: break
print('fuzz3[%s] seed %d checked %d bad %d skip %d'%(mode,seed,done,bad,skip))
PYEOF
(for s in 1 2 3; do python3 fuzz3.py $s 120 7 lang; done; for s in 4 5 6; do python3 fuzz3.py $s 200 0 canon; done) 2>&1 | grep -E 'fuzz3|DIFF'
